export const getGetSessionAssignmentsUrl = (sessionId: string,
    params?: GetSessionAssignmentsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/sessions/${sessionId}/assignments?${stringifiedParams}` : `/api/sessions/${sessionId}/assignments`
}

